import{_ as e,o as d,c as r,ag as o}from"./chunks/framework.BPmc_f4o.js";const m=JSON.parse('{"title":"Driver Tags","description":"Controlled tag vocabulary for driver manifests.","frontmatter":{"title":"Driver Tags","description":"Controlled tag vocabulary for driver manifests."},"headers":[],"relativePath":"reference/driver-tags.md","filePath":"reference/driver-tags.md"}'),a={name:"reference/driver-tags.md"};function c(i,t,s,n,l,p){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="driver-tags" tabindex="-1">Driver Tags <a class="header-anchor" href="#driver-tags" aria-label="Permalink to &quot;Driver Tags&quot;">​</a></h1><p>Drivers declare <code>tags: string[]</code> in their <a href="./driver-manifest.html">manifest</a> to help users discover them in the Extensions panel and marketplace. Tags are drawn from a small controlled vocabulary so search is predictable.</p><p>Tags are validated by <code>node drivers.js validate</code> — unknown tags produce a warning.</p><h2 id="vocabulary" tabindex="-1">Vocabulary <a class="header-anchor" href="#vocabulary" aria-label="Permalink to &quot;Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tag</th><th>For</th></tr></thead><tbody><tr><td><code>spectroscopy</code></td><td>Spectrometers, monochromators, optical analyzers</td></tr><tr><td><code>motion</code></td><td>Robots, CNC, stages, actuators, kinematic motion</td></tr><tr><td><code>camera</code></td><td>Cameras (webcam, IP, ONVIF, machine vision)</td></tr><tr><td><code>robotics</code></td><td>Industrial / collaborative robots specifically</td></tr><tr><td><code>power</code></td><td>Power supplies, batteries, electronic loads</td></tr><tr><td><code>daq</code></td><td>Data acquisition, digitizers, oscilloscopes, multimeters</td></tr><tr><td><code>io</code></td><td>General-purpose digital / analog I/O</td></tr><tr><td><code>serial</code></td><td>Serial-line protocols (UART, RS-232, RS-485)</td></tr><tr><td><code>networking</code></td><td>TCP/UDP, LXI, MQTT, HTTP transports</td></tr><tr><td><code>cnc</code></td><td>CNC-specific (g-code, GRBL)</td></tr><tr><td><code>plotter</code></td><td>Pen plotters</td></tr><tr><td><code>laser</code></td><td>Laser cutters/engravers</td></tr><tr><td><code>monitor</code></td><td>Raw monitoring / terminal tools</td></tr><tr><td><code>terminal</code></td><td>Interactive terminal-like tools</td></tr><tr><td><code>arduino</code></td><td>Arduino-family MCUs</td></tr><tr><td><code>esp32</code></td><td>ESP32-family MCUs</td></tr><tr><td><code>gcode</code></td><td>G-code-speaking devices</td></tr><tr><td><code>grbl</code></td><td>GRBL firmware</td></tr><tr><td><code>drawing</code></td><td>Drawing / vector output</td></tr><tr><td><code>canvas</code></td><td>Canvas-style 2D drawing APIs</td></tr><tr><td><code>pen</code></td><td>Pen-holding devices</td></tr><tr><td><code>axidraw</code></td><td>AxiDraw-specific</td></tr><tr><td><code>audio</code></td><td>Audio output, sound I/O</td></tr><tr><td><code>synth</code></td><td>Software or hardware synthesizers</td></tr><tr><td><code>notification</code></td><td>Alerting / user-feedback helpers (beeps, chimes)</td></tr><tr><td><code>midi</code></td><td>MIDI instruments, controllers, or file playback</td></tr><tr><td><code>printer</code></td><td>Printers and print spoolers (label, receipt, document)</td></tr><tr><td><code>label</code></td><td>Label design / label printing</td></tr><tr><td><code>barcode</code></td><td>Barcode and 2D-code generation or scanning</td></tr><tr><td><code>other</code></td><td>Fallback when no tag fits — rare</td></tr></tbody></table><p>Use 1–8 tags per driver. If you need a new tag that isn&#39;t in this list, request it through the driver registry or support — the controlled vocabulary is maintained centrally.</p>',6)])])}const u=e(a,[["render",c]]);export{m as __pageData,u as default};
